'use strict';
const D=window.JUDO_DATA, C=window.JUDO_COURSE, V=window.JUDO_VIDEOS, R=window.JUDO_RANKS, T=window.JUDO_SPEECH, G=window.JUDO_COACH, X=window.JUDO_EXERCISE;
const KEY='judo-shodan-academy-v1'; // Preserve the original app's storage on the same website.
const fresh=()=>({lessons:{},skills:{},skillLevels:{},lessonSteps:{},reflections:{},activityLog:[],reviews:{},rankChecks:{},journal:[],exerciseLog:[],exercisePrefs:{},quizHistory:[],settings:{},profile:null,journey:'first'});
let S;try{S={...fresh(),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{S=fresh()}
