const app=document.getElementById('app');
let page=S.profile?'home':'welcome', detailId='', search='',filter='All', studyCategory='All', activeCard=null, flipped=false, quiz=null, quizScope='All', forceNew=false, lessonStep=0, workoutId='first-day', journalPrefill='', audioMode=!!S.settings?.audioMode;
