const totalMinutes=()=>S.journal.reduce((v,x)=>v+(Number(x.minutes)||0),0);
const chapters=C.syllabus;
function save(){try{localStorage.setItem(KEY,JSON.stringify(S))}catch{alert('Unable to save locally. Export your data from Settings.') }}
function navigate(to,id=''){page=to;detailId=id;search='';filter='All';if(to!=='review')flipped=false;if(to==='lesson')lessonStep=0;window.scrollTo({top:0,behavior:'instant'});render()}
const ranks=C.rankOptions.map(([value,label])=>`<option value="${attr(value)}">${h(label)}</option>`).join('');
function today(){let d=new Date(),offset=d.getTimezoneOffset();return new Date(d.getTime()-offset*60000).toISOString().slice(0,10)}
function highlight(id){return `<span class="flag ${completed(id)?'done':'pending'}">${completed(id)?'✓ Learned':'To learn'}</span>`}
function progressBar(n,total){return `<div class="bar" role="progressbar" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="${total}"><span style="width:${p(n,total)}%"></span></div>`}
function scopeLessonIds(key){return journeyByKey(key).lessonIds.filter(id=>lessonById[id])}
function layout(){document.querySelectorAll('nav [data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===page||(['lesson','journey'].includes(page)&&b.dataset.route==='learn')||(['technique','videos'].includes(page)&&b.dataset.route==='library')||(['train','journal','exercise','exerciseProgram','exerciseMovement'].includes(page)&&b.dataset.route==='train')||(['quiz','kata','settings','resources','ranks','profile'].includes(page)&&b.dataset.route==='more')));const top=document.querySelector('.brand-sub');if(top)top.textContent=S.profile?(S.profile.rank||'Judo student')+' · Learn at your pace':'Learn judo from day one';document.body.classList.toggle('onboarding',!S.profile)}
function render(){const r={welcome,home,learn,journey,lesson,library,technique,review,quiz:quizScreen,journal,train:trainPage,exercise:exerciseScreen,exerciseProgram:exerciseProgramScreen,exerciseMovement:exerciseMovementScreen,kata,resources,more,settings,profile,ranks:ranksPage,videos:videosPage};app.innerHTML=(r[page]||home)();layout()}
function welcome(){return `<section class="welcome-hero"><span class="bigkanji">柔道</span><span class="eyebrow">Your judo journey starts here</span><h1>Judo Academy</h1><p class="sub">From your first bow to advanced kata and competition. Learn Japanese terminology, explore techniques, train with purpose, and keep track of your journey.</p><div class="hint">Anyone can begin at white belt. If you've already trained, choose your current level instead.</div></section><form id="profileForm" class="panel"><h2>Create your learning profile</h2><label>What should the app call you? <span class="muted">(optional)</span><input name="name" class="field" maxlength="60" placeholder="Your name or nickname" autocomplete="off"></label><label>Your current belt / grade<select class="field" name="rank">${ranks}</select></label><label>Affiliation or rank system<select class="field" name="organization"><option value="Not sure">Not sure yet</option><option value="USJF">USJF</option><option value="USA Judo">USA Judo</option><option value="USJA">USJA</option><option value="Kodokan">Kodokan</option><option value="Other / local dojo">Other / local dojo</option></select></label><label>What interests you most?<select class="field" name="goal"><option value="first">Starting judo</option><option value="fundamentals">Improving fundamentals</option><option value="blackbelt">Working toward black belt</option><option value="sport">Competing</option><option value="heritage">Kata, history, and teaching</option></select></label><p class="small muted">No account needed. This information is stored only in this browser unless you export a backup.</p><button class="primary full" type="submit">Enter the dojo →</button></form>`}
const weeklyGoal=()=>Number(S.settings?.weeklyGoalMinutes)||120;
const skillLevel=id=>Number(S.skillLevels[id]??(S.skills[id]?1:0))||0;
const stageLabels=['Not started','Introduced','Understood','Demonstrated','Applied in randori'];
function markActivity(kind,detail=''){S.activityLog.unshift({when:new Date().toISOString(),kind,detail});S.activityLog=S.activityLog.slice(0,1500)}
function lessonChecklist(id){const a=S.lessonSteps[id];return Array.isArray(a)?a:[false,false,false,false]}
function loggedDays(){return [...new Set([...S.journal.map(x=>x.date),...S.activityLog.map(x=>String(x.when||'').slice(0,10))].filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x)))].sort()}
function streakCount(){const a=new Set(loggedDays());const now=new Date(today()+'T12:00:00');let run=0; if(!a.has(today()))now.setDate(now.getDate()-1);for(let i=0;i<1000;i++){const y=now.getFullYear(),m=String(now.getMonth()+1).padStart(2,'0'),d=String(now.getDate()).padStart(2,'0');if(!a.has(`${y}-${m}-${d}`))break;run++;now.setDate(now.getDate()-1)}return run}
function recentMinutes(days=7){const ms=Date.now()-days*86400000;return S.journal.filter(x=>new Date(x.date+'T12:00:00').getTime()>=ms).reduce((n,x)=>n+(Number(x.minutes)||0),0)}
function weekBars(){const a=[];for(let i=6;i>=0;i--){const d=new Date(today()+'T12:00:00');d.setDate(d.getDate()-i);const date=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');const min=S.journal.filter(x=>x.date===date).reduce((n,x)=>n+(Number(x.minutes)||0),0);a.push({date,day:d.toLocaleDateString(undefined,{weekday:'short'}).slice(0,2),min})}return a}
function chartWeek(){const bars=weekBars(),max=Math.max(60,...bars.map(x=>x.min));return `<div class="weekly-chart" role="img" aria-label="Training time by day: ${bars.map(x=>x.day+' '+x.min+' minutes').join(', ')}">${bars.map(x=>`<div class="weekcol"><strong>${x.min||''}</strong><div class="weektrack"><div class="weekfill" style="height:${x.min?Math.max(6,100*x.min/max):0}%"></div></div><small>${x.day}</small></div>`).join('')}</div>`}
function workoutChoice(){const p=S.profile?.rank==='White belt'?'first-day':(S.journey==='blackbelt'?'throw-families':S.journey==='heritage'?'kata':S.journey==='sport'?'steps':'ne-waza');return G.workouts.find(x=>x.id===p)||G.workouts[0]}
function home(){if(!S.profile)return welcome();const route=journeyByKey(S.journey),ids=scopeLessonIds(route.key),done=learntCount(ids),next=ids.find(x=>!completed(x)),l=lessonById[next],due=D.vocabulary.filter(c=>!S.reviews[c.id]||Number(S.reviews[c.id].due)<=Date.now()).length,w=workoutChoice(),lessonsDone=Object.values(S.lessons).filter(Boolean).length;return `<section class="today-hero"><div class="row between"><span class="eyebrow">TODAY · ${h(new Date().toLocaleDateString(undefined,{month:'long',day:'numeric'}))}</span><span class="rank-pill">${h(S.profile.rank||'Judoka')}</span></div><h1>${S.profile.name?'Hello, '+h(S.profile.name):'Keep growing in judo.'}</h1><p class="sub">One lesson. A little Japanese. One focused practice.</p><div class="daily-summary"><span><strong>${due}</strong><small>cards due</small></span><span><strong>${streakCount()}</strong><small>study streak</small></span><span><strong>${Math.round(recentMinutes()/60*10)/10}h</strong><small>last 7 days</small></span></div></section><div class="section-heading"><h2>Your next steps</h2><button class="ghost small" data-go="learn">All paths →</button></div><div class="today-grid"><button class="next-action main-action" data-go="${l?'lesson':'journey'}" data-id="${attr(l?l.id:route.key)}"><span class="activity-icon blue">▤</span><span class="activity-copy"><small>01 · LEARN</small><strong>${h(l?l.title:'Review your learning path')}</strong><em>${h(route.title)} · ${done}/${ids.length} lessons</em></span><span class="arrow">›</span></button><button class="next-action" data-go="review"><span class="activity-icon green">字</span><span class="activity-copy"><small>02 · REMEMBER</small><strong>${due?due+' Japanese cards due':'Keep your vocabulary fresh'}</strong><em>Smart review based on your recall</em></span><span class="arrow">›</span></button><button class="next-action" data-go="train" data-id="${attr(w.id)}"><span class="activity-icon orange">◉</span><span class="activity-copy"><small>03 · PRACTICE</small><strong>${h(w.title)}</strong><em>${w.minutes} minute coached mat assignment</em></span><span class="arrow">›</span></button></div><div class="panel dashboard-trend"><div class="row between"><div><span class="eyebrow">MAT TIME</span><h2>This week</h2></div><button class="ghost small" data-go="journal">Log session →</button></div>${chartWeek()}<p class="small muted">Only journaled training sessions appear here. No hours are estimated.</p></div><div class="exercise-home-shelf"><span class="eyebrow">OFF THE MAT</span><button class="exercise-home-action" data-go="exercise"><span class="exercise-home-mark">✦</span><span><strong>Strength, mobility & recovery</strong><small>23 guided programs · Plan a stronger judo week</small></span><span aria-hidden="true">›</span></button></div><div class="section-heading"><h2>Explore your judo</h2></div><div class="quick-links"><button data-go="library"><span>技</span><strong>${allTechs.filter(x=>x.official).length} techniques</strong><small>Video encyclopedia</small></button><button data-go="ranks"><span>段</span><strong>Belt progress</strong><small>Study milestones</small></button><button data-go="quiz"><span>✓</span><strong>Quizzes</strong><small>Check recall</small></button><button data-go="journal"><span>✎</span><strong>${S.journal.length} sessions</strong><small>Training history</small></button></div><div class="panel aside"><span class="eyebrow">YOUR LEARNING DATA</span><p>${lessonsDone} studied lessons · ${Object.values(S.skillLevels).filter(x=>x>=3).length} techniques self-reported at demonstration level or higher. Progress is not an official promotion assessment.</p></div>`}
function learn(){return `<span class="eyebrow">Explore the curriculum</span><h1>Choose your path</h1><p class="sub">Start anywhere, or follow a structured journey. Beginners should begin with <strong>My first month</strong>; experienced judoka can move directly to the material they need.</p><div class="journeygrid">${C.routes.map(r=>{const ids=scopeLessonIds(r.key),count=learntCount(ids);return `<button class="journey-card" data-go="journey" data-id="${r.key}"><div class="row between"><span class="journey-mark">${r.key==='first'?'壱':r.key==='blackbelt'?'黒':r.key==='sport'?'勝':r.key==='heritage'?'道':'技'}</span><span class="small muted">${count}/${ids.length}</span></div><h2>${h(r.title)}</h2><p>${h(r.subtitle)}</p>${progressBar(count,ids.length)}</button>`}).join('')}</div><h2>Browse by subject</h2><div class="subjectgrid">${chapters.map(s=>`<button class="subject-pill ${s.tone}" data-browse="${s.key}"><span>${s.icon}</span><strong>${h(s.label)}</strong><small>${h(s.subtitle)}</small></button>`).join('')}</div><div class="panel"><strong>How belt progression works</strong><p class="small muted">Belt colors and kyu grades differ between adult, junior and national programs. This app uses learning stages for convenience and never promotes you automatically. Choose your actual rank in Settings and check grading requirements with your instructor.</p></div>`}
function journey(){const r=journeyByKey(detailId),ids=scopeLessonIds(r.key),done=learntCount(ids);S.journey=r.key;save();return `<button class="ghost" data-go="learn">← All learning paths</button><span class="eyebrow">Learning pathway</span><h1>${h(r.title)}</h1><p class="sub">${h(r.subtitle)}</p><div class="panel"><div class="row between"><strong>${done} of ${ids.length} lessons completed</strong><span>${p(done,ids.length)}%</span></div>${progressBar(done,ids.length)}<p class="small muted">Tap a lesson to view explanations, videos, practice prompts and a self-check.</p></div>${ids.map((id,i)=>{const l=lessonById[id];return `<div class="lesson-row"><button data-go="lesson" data-id="${attr(id)}" class="lesson-click"><span class="ordinal">${i+1}</span><span><strong>${h(l.title)}</strong><small>${h(l.goal)}</small></span></button><label title="Mark as studied"><input type="checkbox" data-lesson="${attr(id)}" ${completed(id)?'checked':''} aria-label="Completed ${attr(l.title)}"></label></div>`}).join('')}`}
function legacyContent(l){let a=[],drills=[],question=[];let n=l.oldNumber;
if(n<=5){a=['Learn the Japanese term, its English meaning, and what it changes about your movement.','Watch a skilled demonstration from the Kodokan or your instructor.','Explain it without relying on BJJ terminology, then use it in cooperative practice.'];drills=['Repeat the term aloud and explain it to a partner.','Record one correction your instructor gave you.'];}
else if(n===6){a=['Kodokan standing throwing techniques are grouped into te, koshi, ashi, ma sutemi and yoko sutemi waza.','Learn the category using representative techniques rather than literal translation alone.'];}
else if(n>=7&&n<=11){let g=D.groups[n-7];a=['Know the name, translation and Kodokan classification of every technique listed below.','For each, identify safe grips, movement, kuzushi, tsukuri and kake under coaching.','Compare the cooperative form with what changes under controlled resistance.'];drills=['Choose two techniques for coach-supervised uchikomi.','Use your journal to note whether timing, grips or footwork caused difficulty.'];}
else if(n===13){a=['Osaekomi waza are formal hold-down techniques. Study positioning, control, transitions and escapes.','Pinning should be controlled; release promptly for taps and commands.'];}
else if(n===15||n===16){a=['Learn the Kodokan terminology and recognize the positions before attempting application.','Choking and joint locking techniques require qualified supervision, age-appropriate rules, and immediate release on a tap.','Practice entries, defensive recognition and control rather than trying to force a finish.'];}
else if(n>=23&&n<=27){a=['Study the correct sequence, etiquette, attack, defensive response, timing and partner roles.','Formal kata requires precision as well as safe execution. A qualified kata instructor is essential.'];drills=['Watch one set in its full sequence.','Explain the role of tori and uke before practicing at reduced speed.'];}
else if(n===28){a=['Understand Jigoro Kano’s educational aims and the founding of Kodokan in 1882.','Relate seiryoku zenyo and jita kyoei to daily dojo practice.'];}
else if(n===29){a=['Recognize common referee commands and signals.','Current rules may change by event, federation or age group; always verify the latest event rulebook.'];}
else{a=['Know the core Japanese vocabulary, physical principles and safety considerations.','Explain the technique or concept, then demonstrate with a qualified instructor.','Be able to describe when it does and does not apply during randori.'];}
return {a,drills,question};}
function lesson(){const l=lessonById[detailId];if(!l)return '<h1>Lesson not found</h1>';let content=l.explain.length?{a:l.explain,drills:l.practice,question:l.reflect}:legacyContent(l);let names=[];
if(l.oldNumber>=7&&l.oldNumber<=11)names=D.groups[l.oldNumber-7].map(t=>({name:t[0],detail:t[1]+' · '+t[2]+' waza'}));
else if(l.oldNumber===13)names=allTechs.filter(t=>t.category==='Osaekomi waza').map(t=>({name:t.name,detail:t.meaning}));
else if(l.oldNumber===15)names=allTechs.filter(t=>t.category==='Shime waza').map(t=>({name:t.name,detail:t.meaning}));
else if(l.oldNumber===16)names=allTechs.filter(t=>t.category==='Kansetsu waza').map(t=>({name:t.name,detail:t.meaning}));
else if(l.oldNumber>=23&&l.oldNumber<=27)names=D.kata[l.oldNumber-23].slice(1).map(name=>({name,detail:'Nage no Kata'}));
else if(l.oldNumber===12)names=allTechs.filter(t=>t.section==='Nage waza'&&!t.set).map(t=>({name:t.name,detail:t.meaning}));
const source= l.search&&Array.isArray(l.search)?l.search[0]:l.search||l.title;
const steps=lessonChecklist(l.id), titles=['Learn','Watch','Practice','Reflect'],step=lessonStep;const cards=[`<div class="panel lesson-content"><h2>Understand the idea</h2>${content.a.map(x=>`<p>${h(x)}</p>`).join('')}${names.length?`<h3>Techniques featured</h3>${names.slice(0,12).map(t=>{const found=allTechs.find(x=>x.name===t.name);return `<div class="techrow"><div><strong>${h(t.name)}</strong><small>${h(t.detail)}</small></div>${found?`<button class="chip" data-go="technique" data-id="${attr(found.id)}">Explore →</button>`:videoLink(t.name)}</div>`}).join('')}`:''}</div>`,`<div class="panel lesson-content"><h2>Watch with purpose</h2><p>Notice posture, distance, timing and how uke lands. Pause the video before the finish and predict what happens next.</p><div class="actions">${videoLink(source)}${link('https://kdkjd.org/names-of-judo-techniques/','Kodokan technique directory')}</div><div class="watch-prompts"><strong>While watching, look for:</strong><ul><li>Where does uke’s balance begin to change?</li><li>What position does tori establish first?</li><li>How is uke kept safe?</li></ul></div><p class="tiny muted">Videos and external websites require internet access.</p></div>`,`<div class="panel lesson-content"><h2>Take it to the tatami</h2><ol class="readable-list">${(content.drills.length?content.drills:['Explain the Japanese term to a partner.','Perform coach-approved cooperative drills before resistance.','Record one correction from your instructor.']).map(s=>`<li>${h(s)}</li>`).join('')}</ol><p class="safety"><strong>Train with supervision:</strong> Videos do not replace qualified instruction. Never practice throws, chokes or joint locks beyond your level.</p><button class="secondary" data-go="journal">Open training journal →</button></div>`,`<div class="panel lesson-content"><h2>Teach it back</h2><p>${h(content.question[0]||`What is the most important thing you learned about ${l.title}?`)}</p><label>My own explanation<textarea class="field" id="lessonReflection" rows="5" maxlength="1500" placeholder="Explain it in your own words…">${h(S.reflections[l.id]||'')}</textarea></label><button class="secondary" data-save-reflection="${attr(l.id)}">Save reflection</button><details><summary>What should a good answer include?</summary><p class="muted small">Describe the Japanese terms, purpose, safe partner interaction and one thing your coach should verify.</p></details><button class="secondary" data-go="quiz">Knowledge quiz →</button></div>`];return `<button class="ghost" data-go="journey" data-id="${attr(S.journey)}">← Learning path</button><span class="eyebrow">${h(l.path==='shodan'?'Black belt study':chapters.find(x=>x.key===l.path)?.label||'Judo lesson')} · ${h(l.level)}</span><h1>${h(l.title)}</h1><p class="lead">${h(l.goal)}</p><div class="lesson-steps">${titles.map((t,i)=>`<button class="lesson-step ${step===i?'selected':''} ${steps[i]?'finished':''}" data-lesson-tab="${i}" aria-current="${step===i?'step':'false'}"><span>${steps[i]?'✓':i+1}</span><small>${t}</small></button>`).join('')}</div>${cards[step]}<div class="panel guided-next"><span class="small muted">Step ${step+1} of 4 · ${steps.filter(Boolean).length} reviewed</span><div class="actions">${step>0?`<button class="secondary" data-lesson-back>← Previous</button>`:''}<button class="primary" data-lesson-continue="${attr(l.id)}">${step===3?'Finish lesson':'Mark step reviewed →'}</button></div></div><div class="panel"><label class="row"><input type="checkbox" data-lesson="${attr(l.id)}" ${completed(l.id)?'checked':''}><strong>I have studied and practiced this lesson</strong></label><p class="small muted">Self-assessment only. Ask your instructor to verify physical technique quality.</p></div>`}
function library(){return `<span class="eyebrow">Technique encyclopedia</span><h1>Explore judo techniques</h1><p class="sub">${allTechs.filter(t=>t.official).length} official Kodokan techniques plus ${allTechs.filter(t=>!t.official).length} additional variations. Browse throws, holds, strangles and joint locks.</p><input class="field search" type="search" id="techSearch" placeholder="Search Japanese or English names…" value="${attr(search)}" aria-label="Search techniques"><div class="filters">${['All','Gokyo','Te waza','Koshi waza','Ashi waza','Ma sutemi waza','Yoko sutemi waza','Osaekomi waza','Shime waza','Kansetsu waza'].map(cat=>`<button class="chip ${filter===cat?'active':''}" data-filter="${cat}">${cat}</button>`).join('')}</div><div id="techResults">${renderTechs()}</div><p class="note small">Some historically recognized techniques are prohibited under modern competition rules. See the current federation rulebook before shiai.</p>`}
function renderTechs(){let q=search.trim().toLowerCase(),items=allTechs.filter(t=>(filter==='All'||filter==='Gokyo'&&t.set>0||t.category===filter)&&[t.name,t.meaning,t.category].some(s=>s.toLowerCase().includes(q)));return `<p class="small muted">Showing ${items.length} results · ${Object.keys(G.guides).length} detailed technique study guides</p>${items.map(t=>`<div class="techrow"><button class="techclick" data-go="technique" data-id="${t.id}"><strong>${h(t.name)}</strong><small>${h(t.meaning)} · ${h(t.category)}${t.set?' · Gokyo '+t.set:''}${G.guides[t.id]?' · ★ Study guide':''}</small></button><button class="level-token" data-go="technique" data-id="${t.id}" aria-label="Technique progress: ${h(stageLabels[skillLevel(t.id)])}">${skillLevel(t.id)?'L'+skillLevel(t.id):'›'}</button></div>`).join('')||'<div class="panel">No matching techniques. Try a different name or category.</div>'}`}
function technique(){const t=allTechs.find(x=>x.id===detailId);if(!t)return '<h1>Technique not found</h1>';const g=G.guides[t.id],level=skillLevel(t.id),related=(g?.links||[]).map(name=>allTechs.find(x=>x.name===name)).filter(Boolean);const general=t.section==='Nage waza'?['Kuzushi: identify the direction and timing of the off balance.','Tsukuri: find the correct foot placement, grip and posture.','Kake: observe how the throw finishes with uke under control.']:t.category==='Osaekomi waza'?['Recognize the controlled position and how weight is distributed.','Practice coach-approved transitions and escapes at low resistance.','Release immediately for a stop or partner request.']:['Recognize the formal position and competition restrictions.','Practice only with qualified supervision and appropriate eligibility.','Release immediately for a tap or verbal stop.'];return `<button class="ghost" data-go="library">← Encyclopedia</button><div class="eyebrow">${h(t.section)} · ${h(t.category)}${g?' · IN-DEPTH GUIDE':''}</div><h1>${h(t.name)}</h1><p class="lead">${h(t.meaning)}</p><div class="phonetics"><span class="kana">${h(T.kana(t.name))}</span>${speechButtons(t.name)}</div><section class="tech-video"><div class="video-badge">▶ KODOKAN REFERENCE</div><h2>Watch the demonstration</h2><p>Watch slowly and look for posture, timing, safe partner control and the direction of movement.</p>${videoLink(t.name)}<small>Official video opens on YouTube. Requires internet.</small></section>${g?`<div class="panel technique-guide"><span class="eyebrow">THE CENTRAL IDEA</span><p class="lead">${h(g.idea)}</p><div class="coach-points">${[['Kuzushi / control',g.kuzushi],['Tsukuri / position',g.entry],['Kake / finish',g.finish]].map(([name,value],i)=>`<div class="coach-point"><span>${i+1}</span><div><strong>${h(name)}</strong><p>${h(value)}</p></div></div>`).join('')}</div></div><div class="panel"><h2>Common mistakes to recognize</h2><ul class="readable-list">${g.errors.map(x=>`<li>${h(x)}</li>`).join('')}</ul></div><div class="panel"><h2>Coach-approved mat assignment</h2><p>${h(g.drill)}</p><button class="secondary" data-practice-tech="${attr(t.id)}">Log this focus →</button></div>${related.length?`<div class="panel"><h2>Related techniques</h2>${related.map(x=>`<button class="more-row" data-go="technique" data-id="${attr(x.id)}"><strong>${h(x.name)}</strong><small>${h(x.meaning)}</small><span>›</span></button>`).join('')}</div>`:''}`:`<div class="panel"><h2>Study checklist</h2><p class="small muted">This technique currently has a reference checklist rather than a full written coaching guide.</p><ul class="readable-list">${general.map(x=>`<li>${h(x)}</li>`).join('')}</ul><button class="secondary" data-practice-tech="${attr(t.id)}">Log practice →</button></div>`}<div class="panel skill-stage"><span class="eyebrow">PERSONAL DEVELOPMENT</span><h2>How well do you know this?</h2><p class="small muted">Choose the highest level you can support with your own training. These are self-reported milestones, not belt exam sign-offs.</p><div class="stage-options">${stageLabels.map((x,i)=>`<button class="stage-choice ${level===i?'chosen':''}" data-level="${i}" data-tech="${attr(t.id)}" aria-pressed="${level===i}"><span>${level===i?'●':'○'}</span><strong>${h(x)}</strong></button>`).join('')}</div></div><div class="panel safety"><strong>Partner safety</strong><p>Use formal coaching for physical practice. Kodokan classification does not mean a technique is legal for your competition division.</p></div>`}
function dueCards(){return D.vocabulary.filter(c=>(studyCategory==='All'||c.category===studyCategory)&&(!S.reviews[c.id]||Number(S.reviews[c.id].due)<=Date.now()))}
function review(){const cats=['All',...new Set(D.vocabulary.map(c=>c.category))],due=dueCards();let all=D.vocabulary.filter(c=>studyCategory==='All'||c.category===studyCategory),pool=due.length?due:all;if(!pool.length)return '<h1>No cards</h1>';if(!activeCard||!pool.some(x=>x.id===activeCard))activeCard=pool[0].id;let c=D.vocabulary.find(x=>x.id===activeCard);return `<span class="eyebrow">Practice Japanese</span><h1>Flashcards</h1><p class="sub">${due.length} due out of ${all.length} terms in this category. Reveal the meaning and rate your recall.</p><button class="chip ${audioMode?'active':''}" data-audio-mode aria-pressed="${audioMode}">◖)) Audio recognition ${audioMode?'on':'off'}</button><div class="filters">${cats.map(x=>`<button class="chip ${studyCategory===x?'active':''}" data-card-category="${attr(x)}">${h(x)}</button>`).join('')}</div><button class="flashcard" data-flip="1"><small>${h(c.category)}</small><strong>${flipped?h(c.back):audioMode?'Listen and recall the meaning':h(c.front)}</strong><span>${flipped?h(c.front):'Tap to reveal the English meaning'}</span></button><div class="phonetics flash-phonetics"><span class="kana">${audioMode&&!flipped?'?':h(T.kana(c.front))}</span>${speechButtons(c.front)}</div>${flipped?`<div class="grading"><button class="secondary" data-grade="1">Again</button><button class="secondary" data-grade="3">Hard</button><button class="primary" data-grade="4">Good</button><button class="primary" data-grade="5">Easy</button></div>`:'<p class="small muted">Cards you miss come back sooner. You can review them even when you’re offline.</p>'}${!due.length?'<p class="note small">All scheduled reviews are done. You can still keep practicing.</p>':''}`}
function grade(g){const prev=S.reviews[activeCard]||{reps:0,interval:0,ease:2.5};const ease=Math.max(1.3,prev.ease+(0.1-(5-g)*(0.08+(5-g)*0.02)));const reps=g<3?0:prev.reps+1;const days=g<3?0:g===3?1:reps===1?1:reps===2?6:Math.max(1,Math.round(prev.interval*ease));const minutes=g<3?2:0;S.reviews[activeCard]={reps,ease,interval:days,due:Date.now()+(minutes?minutes*60000:days*86400000),last:Date.now()};markActivity('flashcard',activeCard);save();activeCard=dueCards().find(c=>c.id!==activeCard)?.id||null;flipped=false;render()}
function getQuizPool(){const all=[...C.quizBank,...D.quizQuestions.map(q=>({...q,path:'shodan'})),...G.quizBank];const pool=quizScope==='All'?all:['vocab','techniques'].includes(quizScope)?all.filter(q=>q.kind===quizScope):all.filter(q=>q.path===quizScope||quizScope==='core'&&q.path==='start');const shuffled=[...pool];for(let i=shuffled.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[shuffled[i],shuffled[j]]=[shuffled[j],shuffled[i]]}return shuffled.slice(0,Math.min(10,shuffled.length))}
function beginQuiz(){quiz={items:getQuizPool(),index:0,score:0,selected:null};render()}
function quizScreen(){if(!quiz)return `<span class="eyebrow">Knowledge assessment</span><h1>Quiz center</h1><p class="sub">Choose an area, then answer up to ten questions. Includes vocabulary, official technique names, classifications and judo theory. Scores measure recall, not technical ability or rank eligibility.</p><div class="panel"><label>Study area<select id="quizScope" class="field"><option value="All" ${quizScope==='All'?'selected':''}>All judo</option><option value="vocab" ${quizScope==='vocab'?'selected':''}>Japanese vocabulary</option><option value="techniques" ${quizScope==='techniques'?'selected':''}>Technique recognition</option>${chapters.map(x=>`<option value="${x.key}" ${quizScope===x.key?'selected':''}>${h(x.label)}</option>`).join('')}</select></label><button class="primary full" data-start-quiz>Start quiz →</button></div>${S.quizHistory.length?`<div class="panel"><h2>Recent scores</h2>${S.quizHistory.slice(0,8).map(x=>`<div class="row between minirow"><span>${h(new Date(x.date).toLocaleDateString())}</span><strong>${Number(x.score)}/${Number(x.total)}</strong></div>`).join('')}</div>`:''}`;
if(quiz.index>=quiz.items.length)return `<span class="eyebrow">Quiz complete</span><h1>Your results</h1><div class="panel center"><div class="score">${quiz.score}/${quiz.items.length}</div><p>${p(quiz.score,quiz.items.length)}% correct</p><p class="muted">${quiz.score===quiz.items.length?'Strong recall. Try another topic.':'Review your missed terms, then give it another try.'}</p><div class="actions centered"><button class="primary" data-start-quiz>Try again</button><button class="secondary" data-reset-quiz>Choose topic</button></div></div>`;
const q=quiz.items[quiz.index];return `<span class="eyebrow">Question ${quiz.index+1} of ${quiz.items.length}</span><h1>Knowledge quiz</h1>${progressBar(quiz.index,quiz.items.length)}<div class="panel"><h2>${h(q.question)}</h2><div class="choices">${q.options.map(a=>`<button class="answer ${quiz.selected!==null?(a===q.answer?'correct':quiz.selected===a?'incorrect':''):''}" data-answer="${attr(a)}" ${quiz.selected!==null?'disabled':''}>${h(a)}</button>`).join('')}</div>${quiz.selected!==null?`<p class="note">${quiz.selected===q.answer?'Correct.':'Correct answer: '+h(q.answer)}</p><button class="primary full" data-next-quiz>${quiz.index===quiz.items.length-1?'Finish':'Next question →'}</button>`:''}</div>`}
function trainPage(){if(detailId&&G.workouts.some(x=>x.id===detailId))workoutId=detailId;const w=G.workouts.find(x=>x.id===workoutId)||G.workouts[0];return `<span class="eyebrow">PRACTICE WITH PURPOSE</span><h1>Training</h1><p class="sub">Choose a mat assignment, record what happened, and watch your practice add up. Drills are suggestions for supervised training, not a replacement for a coach.</p><div class="train-metrics"><div class="panel"><strong>${S.journal.length}</strong><small>Logged sessions</small></div><div class="panel"><strong>${Math.round(totalMinutes()/60*10)/10}h</strong><small>Total mat time</small></div><div class="panel"><strong>${streakCount()}</strong><small>Study streak</small></div></div><div class="exercise-train-cta"><span class="eyebrow">NEW · OFF THE MAT</span><h2>Exercise studio</h2><p>Full strength workouts, conditioning, mobility, and joint care exercises with progress tracking.</p><button class="primary full" data-go="exercise">Explore 23 workout programs →</button></div><div class="section-heading"><h2>Choose a practice focus</h2></div><div class="routine-strip">${G.workouts.map(x=>`<button class="routine-chip ${w.id===x.id?'selected':''}" data-workout="${x.id}"><strong>${h(x.title)}</strong><small>${x.minutes} min · ${h(x.level)}</small></button>`).join('')}</div><div class="panel routine-detail"><span class="eyebrow">${h(w.focus).toUpperCase()}</span><h2>${h(w.title)}</h2><p class="small muted">Suggested time ${w.minutes} minutes. Your instructor controls appropriate intensity and technique selection.</p><ol class="readable-list">${w.steps.map(x=>`<li>${h(x)}</li>`).join('')}</ol><button class="primary full" data-workout-journal="${attr(w.id)}">Log practice with this focus →</button></div><div class="panel"><div class="row between"><h2>Training this week</h2><button class="ghost small" data-go="journal">All entries →</button></div>${chartWeek()}${progressBar(Math.min(recentMinutes(),weeklyGoal()),weeklyGoal())}<p class="small muted">${recentMinutes()} / ${weeklyGoal()} minutes toward your weekly practice goal. Change the goal in Settings.</p></div><h2>Your recent sessions</h2>${S.journal.length?S.journal.slice(0,4).map(x=>`<div class="session-preview"><div><strong>${h(x.focus)}</strong><small>${h(x.date)} · ${Number(x.minutes)||0} minutes</small></div><span>✓</span></div>`).join(''):'<div class="panel muted">Your journal is empty. Start with a short note after your next class.</div>'}<button class="secondary full" data-go="journal">Open full training journal</button>`}

/* EXERCISE STUDIO: general conditioning, never a diagnosis or patient-specific rehab plan. */
const xById=Object.fromEntries(X.exercises.map(e=>[e.id,e]));
const xPrById=Object.fromEntries(X.programs.map(e=>[e.id,e]));
const EX_CATS=['All','Strength','Conditioning','Performance','Warmup','Mobility','Joint care','Recovery'];
const xPrefs=()=>({gear:S.exercisePrefs.gear||'None',experience:S.exercisePrefs.experience||'Beginner',judoDays:S.exercisePrefs.judoDays===undefined?2:Number(S.exercisePrefs.judoDays),goal:S.exercisePrefs.goal||'balanced'});
const xSource=(id)=>X.sources[id]||null;
const xSourceHtml=(keys)=>[...new Set((Array.isArray(keys)?keys:[keys]).filter(Boolean))].map(k=>{const v=xSource(k);return v?`<a href="${attr(v.url)}" target="_blank" rel="noopener noreferrer" class="source-pill">↗ ${h(v.label)}</a>`:''}).join('');
const xKind=(k)=>({Strength:'Strength & muscle',Conditioning:'Conditioning',Performance:'Power & performance',Warmup:'Warmups',Mobility:'Mobility',Recovery:'Recovery','Joint care':'PT-informed joint care'})[k]||k;
const xTag=(txt)=>`<span class="x-pill">${h(txt)}</span>`;
const xSafety=`<aside class="x-health-note"><strong>Training safely</strong><p>These are general educational workouts, mostly designed for healthy adults. The joint care section is <strong>not injury treatment</strong>. Stop any activity that causes pain, worsening symptoms, dizziness or loss of control. Seek qualified medical advice for an injury or persistent symptoms. Youth, people with relevant medical conditions, and anyone returning after injury or surgery need individualized guidance.</p></aside>`;
function xSummary(){const sessions=S.exerciseLog.length,total=S.exerciseLog.reduce((sum,r)=>sum+(Number(r.minutes)||0),0);const weekAgo=Date.now()-7*86400000,week=S.exerciseLog.filter(r=>new Date(r.date).getTime()>=weekAgo).length;return `<div class="x-stat-grid"><div><strong>${sessions}</strong><small>Workouts</small></div><div><strong>${Math.round(total/60*10)/10}h</strong><small>Exercise time</small></div><div><strong>${week}</strong><small>Last 7 days</small></div></div>`}
function exerciseScreen(){return `<button class="ghost" data-go="train">← Training</button><section class="x-hero"><div class="row between"><span class="eyebrow">PHYSICAL PREPARATION</span><span class="x-hero-icon">✦</span></div><h1>Exercise studio</h1><p>Get stronger for judo. Move better. Train for the long game.</p><div class="x-hero-stats"><span>65 exercises</span><span>23 programs</span><span>Offline-ready</span></div></section>
${xSummary()}<div class="x-tabs" role="tablist" aria-label="Exercise sections">${[['programs','Programs'],['plan','My week'],['library','Exercises'],['joint','Joint care'],['history','History']].map(([id,l])=>`<button role="tab" aria-selected="${exerciseTab===id}" class="${exerciseTab===id?'selected':''}" data-ex-tab="${id}">${l}</button>`).join('')}</div>
${exerciseTab==='programs'?exercisePrograms():exerciseTab==='plan'?exercisePlan():exerciseTab==='library'?exerciseLibrary():exerciseTab==='joint'?exerciseJointCare():exerciseHistory()}`;}
function xProgramCard(w){return `<button class="x-program-card" data-ex-program="${attr(w.id)}"><div class="row between"><span class="x-category-label">${h(xKind(w.category))}</span><span class="x-mini-arrow">↗</span></div><strong>${h(w.title)}</strong><p>${h(w.description)}</p><div class="x-program-meta">${xTag(w.minutes+' min')}${xTag(w.level)}${xTag(w.gear)}</div></button>`;}
function exercisePrograms(){const compatible=X.programs.filter(w=>exerciseCategory==='All'||w.category===exerciseCategory).filter(w=>exerciseGear==='All'||w.gear===exerciseGear||w.gear==='None');return `<div class="x-section-heading"><h2>Find a workout</h2><span class="small muted">${compatible.length} programs</span></div><p class="small muted">Pick a program for your goal and equipment. The joint care series is general conditioning, not individual rehabilitation.</p><div class="x-scroll-chips" aria-label="Workout categories">${EX_CATS.map(k=>`<button class="chip ${exerciseCategory===k?'active':''}" data-ex-category="${attr(k)}">${h(xKind(k))}</button>`).join('')}</div><label class="x-filter-label">Available equipment<select class="field" id="xGearFilter">${['All','None','Bands','Dumbbells','Gym'].map(k=>`<option value="${k}" ${exerciseGear===k?'selected':''}>${k==='All'?'Any equipment':k==='None'?'No equipment':k}</option>`).join('')}</select></label><div class="x-card-grid">${compatible.map(xProgramCard).join('')||'<div class="panel muted">No workouts match these filters. Try choosing any equipment.</div>'}</div>${xSafety}${exerciseSources()}`;}
function xCompatible(w,gear){return gear==='Gym'||w.gear==='None'||w.gear===gear||(gear==='Dumbbells'&&w.gear==='None')||(gear==='Bands'&&w.gear==='None');}
function xPlanPrograms(){const q=xPrefs();let a,b;
if(q.gear==='Gym'&&q.experience!=='Beginner'){a=xPrById['gym-strength-a'];b=xPrById['gym-strength-b']}
else if(q.gear==='Dumbbells'){a=xPrById['dumbbell-full'];b=xPrById['strength-foundation-b']}
else if(q.gear==='Bands'){a=xPrById['band-full'];b=xPrById['strength-foundation-b']}
else if(q.experience==='Intermediate'){a=xPrById['bodyweight-advanced'];b=xPrById['strength-foundation-b']}
else{a=xPrById['strength-foundation-a'];b=xPrById['strength-foundation-b']}
const third=q.goal==='conditioning'?xPrById['base-engine']:q.goal==='mobility'?xPrById['mobility-reset']:q.goal==='joints'?xPrById[q.gear==='Gym'||q.gear==='Bands'?'shoulder-care':'knee-care']:xPrById['pre-judo-warmup'];
let days=q.judoDays>=4?[['Day 1','Strength',a],['Day 2','Light mobility',xPrById['mobility-reset']]]:[['Day 1','Strength',a],['Day 3','Strength',b],['Optional','Recovery / goal',third]];
return {days,description:q.judoDays>=4?'You have several judo sessions each week. Keep extra lifting modest, and consider omitting optional sessions when tired.':'Try separating strength sessions by at least a day, and avoid adding intense intervals before demanding randori.'};}
function exercisePlan(){const v=xPrefs(),{days,description}=xPlanPrograms();return `<h2>Your training week</h2><p class="sub">Choose your situation and get a simple starter template. It is not an automated injury treatment plan or a substitute for a coach.</p><form id="exercisePrefsForm" class="panel x-pref-form"><label>Equipment<select class="field" name="gear">${['None','Bands','Dumbbells','Gym'].map(k=>`<option ${v.gear===k?'selected':''}>${k}</option>`).join('')}</select></label><label>Exercise experience<select class="field" name="experience">${['Beginner','Intermediate'].map(k=>`<option ${v.experience===k?'selected':''}>${k}</option>`).join('')}</select></label><label>Judo sessions each week<select class="field" name="judoDays">${[0,1,2,3,4,5,6].map(k=>`<option value="${k}" ${v.judoDays===k?'selected':''}>${k}</option>`).join('')}</select></label><label>Your focus<select class="field" name="goal">${[['balanced','General strength'],['conditioning','Conditioning'],['mobility','Mobility'],['joints','Joint resilience']].map(([id,l])=>`<option value="${id}" ${v.goal===id?'selected':''}>${l}</option>`).join('')}</select></label><button class="primary full" type="submit">Update my week</button></form><div class="x-plan-note">${h(description)}</div>${days.map(([day,label,p])=>`<button class="x-plan-day" data-ex-program="${attr(p.id)}"><span class="x-day-number">${h(day)}</span><span><strong>${h(p.title)}</strong><small>${h(label)} · ${p.minutes} minutes</small></span><span class="x-mini-arrow">›</span></button>`).join('')}<div class="panel"><h2>How to progress</h2><ol class="readable-list"><li>Begin with manageable effort. Leave about 2 to 4 repetitions in reserve.</li><li>Repeat the same movements for several weeks, increasing repetitions first and then load when form is consistent.</li><li>If judo volume increases, reduce extra lifting or conditioning rather than piling on fatigue.</li><li>Schedule at least one lighter day after very demanding sessions; adapt to your recovery.</li></ol><p class="small muted">For adults, general activity guidance includes muscle strengthening on at least two days each week. Sports performance programs are individualized beyond that starting point.</p>${xSourceHtml(['cdc','research'])}</div>${xSafety}`;}
function exerciseLibrary(){const list=X.exercises.filter(x=>`${x.name} ${x.group} ${x.gear}`.toLowerCase().includes(exerciseSearch.toLowerCase()));return `<h2>Exercise encyclopedia</h2><p class="small muted">Each movement includes a starting dose, form cues, substitutions and, where applicable, orthopedic sources. Exercises are not a diagnosis or individualized treatment.</p><label for="exerciseSearch">Search 65 movements</label><input id="exerciseSearch" class="field" type="search" placeholder="Squat, shoulder, ankle, grip…" value="${attr(exerciseSearch)}"><div id="exerciseSearchResults">${exerciseResults(list)}</div>${xSafety}`;}
function exerciseResults(list){return `<div class="x-result-count">${list.length} movements</div>${list.map(e=>`<button class="x-movement-row" data-ex-move="${attr(e.id)}"><span class="x-move-glyph">${h(({['Lower body']:'↟',['Posterior chain']:'∧',['Upper back']:'↗',['Shoulder care']:'◌',['Ankle care']:'◉',['Core']:'◆',['Balance']:'◎'})[e.group]||'✦')}</span><span><strong>${h(e.name)}</strong><small>${h(e.group)} · ${h(e.gear)} · ${h(e.dose)}</small></span><span aria-hidden="true">›</span></button>`).join('')||'<p class="muted">No movements matched. Try a shorter search.</p>'}`;}
function exerciseJointCare(){const ids=['shoulder-care','knee-care','ankle-care','back-care','wrist-care'];return `<h2>Move well for longer</h2><p class="lead">Judo puts repeated demands on shoulders, elbows, knees, ankles and grip. This section collects low-load conditioning and references you can discuss with an instructor or physical therapist.</p><div class="x-health-note"><strong>Not a rehabilitation prescription</strong><p>Do not use these routines to self-treat a current injury. Pain, instability, swelling, numbness, weakness or loss of function may require an assessment. Acute injury, inability to bear weight or significant neurological symptoms need prompt medical attention. Exercises for return to sport should be individualized.</p></div><div class="x-card-grid">${ids.map(id=>xProgramCard(xPrById[id])).join('')}</div><div class="panel"><h2>When physical therapy helps</h2><p>Consider a sports physical therapist for persistent joint pain, recurrent sprains, shoulder instability, repeated grip-related symptoms, or returning after an injury or surgery. A PT can assess strength, range of motion, tolerance for falling, and sport-specific readiness.</p><h3>Bring these questions to a consultation</h3><ol class="readable-list"><li>Which movements or loads are appropriate at my current stage?</li><li>What signs indicate I should reduce or stop training?</li><li>How should I progress resistance, repetition and return to randori?</li><li>What objective tests should I meet before full judo participation?</li></ol></div><div class="panel"><h2>Evidence and background</h2><p>Judo's IPPON intervention was developed as a coach-led warmup emphasizing shoulder, knee and ankle strength, balance and mobility. At publication, evidence that it actually reduced injuries was still being evaluated. The orthopedic links below describe general conditioning with clinical supervision advised for rehabilitation.</p>${xSourceHtml(['ippon','aaos-shoulder','aaos-knee','aaos-ankle','aaos-spine'])}</div>`;}
function exerciseSources(){return `<section class="panel x-sources"><h2>Sources and context</h2><p class="small muted">The program templates are original educational examples informed by these references. They are not official AAOS, CDC, NSCA or IPPON prescriptions or endorsements.</p>${xSourceHtml(Object.keys(X.sources))}</section>`;}
function exerciseHistory(){return `<h2>Your strength & recovery journal</h2><p class="small muted">Workout sessions are separate from judo mat time. They stay private in your device storage and export with your usual backup.</p>${xSummary()}${S.exerciseLog.length?S.exerciseLog.map(x=>`<div class="x-history-card"><div class="row between"><strong>${h(x.title||'Workout')}</strong><small class="muted">${h((x.date||'').slice(0,10))}</small></div><div class="x-program-meta">${xTag((x.minutes||0)+' min')}${xTag((x.items||[]).length+' exercises')}${x.rpe?xTag('RPE '+x.rpe):''}</div>${x.notes?`<p class="small">${h(x.notes)}</p>`:''}<details><summary>Completed exercises</summary><ul class="readable-list">${(x.items||[]).map(a=>`<li>${h(a.name)}${a.load?' · '+h(a.load):''}</li>`).join('')}</ul></details><button class="ghost small danger-text" data-ex-delete="${attr(x.id)}">Delete entry</button></div>`).join(''):'<div class="panel muted">No exercise sessions yet. Choose a program, complete the movements that fit, then log what you did.</div>'}${xSafety}`;}
function captureExerciseDraft(){if(page!=='exerciseProgram')return;exerciseDraft[exerciseProgramId]={checked:[...document.querySelectorAll('[data-ex-done]:checked')].map(x=>x.dataset.exDone),loads:Object.fromEntries([...document.querySelectorAll('[data-ex-load]')].map(x=>[x.dataset.exLoad,x.value])),minutes:document.querySelector('#exerciseLogForm [name=minutes]')?.value||'',rpe:document.querySelector('#exerciseLogForm [name=rpe]')?.value||'',notes:document.querySelector('#exerciseLogForm [name=notes]')?.value||''};}
function exerciseProgramScreen(){const w=xPrById[exerciseProgramId]||X.programs[0],draft=exerciseDraft[w.id]||{};return `<button class="ghost" data-ex-back="exercise">← Exercise studio</button><div class="x-program-hero"><span class="eyebrow">${h(xKind(w.category))}</span><h1>${h(w.title)}</h1><p>${h(w.description)}</p><div class="x-program-meta">${xTag(w.minutes+' min')}${xTag(w.level)}${xTag(w.gear)}</div></div><div class="x-health-note"><strong>Before you start</strong><p>${h(w.intro||'Begin with 5–10 minutes of easy activity and a few light practice reps.')}</p>${w.caution?`<p><strong>Specific caution:</strong> ${h(w.caution)}</p>`:''}<p>Perform movements in a pain-free range. Stop for pain, new symptoms, or loss of control. Rehabilitation requires clinical assessment and guidance.</p></div><div class="row between"><h2>Workout checklist</h2><span class="small muted">${w.items.length} movements</span></div><p class="small muted">Check off what you actually completed. You may log a partial workout. Optional load fields are just your own notes, not a weight recommendation.</p><div id="xWorkoutItems">${w.items.map((it,i)=>{const e=xById[it.id];return `<div class="x-workout-item"><div class="row"><label class="x-complete-label"><input type="checkbox" data-ex-done="${attr(e.id)}" ${draft.checked?.includes(e.id)?'checked':''}><span class="x-index">${i+1}</span><span><strong>${h(e.name)}</strong><small>${h(it.dose||e.dose)} · Rest ${h(e.rest)} · ${h(e.group)}</small></span></label><button class="ghost x-info-btn" data-ex-move="${attr(e.id)}" aria-label="Read how to do ${attr(e.name)}">ⓘ</button></div><details><summary>Technique cues & alternatives</summary><ol class="readable-list">${e.cues.map(c=>`<li>${h(c)}</li>`).join('')}</ol>${e.alt?`<p class="small muted">Alternative: ${h(xById[e.alt]?.name||e.alt)}</p>`:''}${e.note?`<p class="small muted">${h(e.note)}</p>`:''}${e.source?xSourceHtml(e.source):''}</details><label class="x-load-label">Optional load or adjustment <input class="x-load" data-ex-load="${attr(e.id)}" maxlength="70" value="${attr(draft.loads?.[e.id]||'')}" placeholder="e.g. 12 kg, bodyweight, lighter"></label></div>`}).join('')}</div><form id="exerciseLogForm" class="panel x-log-panel"><h2>Finish workout</h2><label>Actual minutes<input class="field" type="number" min="1" max="360" value="${attr(draft.minutes||Math.max(5,Math.min(180,w.minutes)))}" name="minutes" required></label><label>Overall exertion (optional)<select class="field" name="rpe"><option value="">Not recorded</option>${[3,4,5,6,7,8,9,10].map(n=>`<option value="${n}" ${String(draft.rpe||'')===String(n)?'selected':''}>${n} / 10 ${n<=5?'easy':n<=7?'moderate':'hard'}</option>`).join('')}</select></label><label>Notes (optional)<textarea class="field" name="notes" rows="3" maxlength="700" placeholder="How did it feel? What will you adjust next session?">${h(draft.notes||'')}</textarea></label><button class="primary full" type="submit">Save completed workout</button><p class="tiny muted">Logs are self-reported, stored locally and included in your JSON backup.</p></form><div class="panel"><h2>References</h2>${xSourceHtml(w.sources)}<p class="small muted">Program assembled for education from general guidelines, not reproduced from the linked sources.</p></div>`;}
function exerciseMovementScreen(){const e=xById[exerciseMovementId]||X.exercises[0];return `<button class="ghost" data-ex-back="${exerciseHistoryId?'exerciseProgram':'exercise'}">← ${exerciseHistoryId?'Workout':'Exercise studio'}</button><span class="eyebrow">MOVEMENT GUIDE</span><h1>${h(e.name)}</h1><div class="x-program-meta">${xTag(e.group)}${xTag(e.gear)}${xTag(e.level)}</div><div class="panel x-movement-detail"><div class="x-prescription"><div><small>Starting dose</small><strong>${h(e.dose)}</strong></div><div><small>Rest</small><strong>${h(e.rest)}</strong></div></div><h2>Technique cues</h2><ol class="readable-list">${e.cues.map(c=>`<li>${h(c)}</li>`).join('')}</ol>${e.alt?`<p><strong>Alternative:</strong> ${h(xById[e.alt]?.name||e.alt)}</p>`:''}${e.note?`<div class="x-health-note">${h(e.note)}</div>`:''}<div class="actions">${e.source?xSourceHtml(e.source):''}<a class="linkbutton secondary" href="https://www.youtube.com/results?search_query=${encodeURIComponent(e.name+' exercise technique physical therapist')}" target="_blank" rel="noopener noreferrer">Find technique video ↗</a></div></div>${xSafety}`;}

function journal(){return `<button class="ghost" data-go="train">← Training</button><span class="eyebrow">TRACK YOUR MAT TIME</span><h1>Training journal</h1><p class="sub">Record coach feedback, repetition focus and real training time. Your notes stay on this device unless you export them.</p><form id="journalForm" class="panel"><label>Date<input class="field" type="date" name="date" required value="${today()}"></label><label>Session type<select class="field" name="type">${['Class','Randori','Technique / drilling','Kata','Competition','Private lesson','Other'].map(x=>`<option>${h(x)}</option>`).join('')}</select></label><label>What did you practice?<input class="field" name="focus" required maxlength="120" placeholder="Foot sweeps, kata, escapes…" value="${attr(journalPrefill)}"></label><label>Minutes<input class="field" type="number" name="minutes" min="0" max="600" value="60" required></label><label>Training intensity<select class="field" name="intensity"><option value="">Not specified</option><option value="Light">Light</option><option value="Moderate">Moderate</option><option value="Hard">Hard</option></select></label><label>Notes and coaching feedback<textarea class="field" name="notes" rows="5" maxlength="3000" placeholder="What worked? What correction will you remember?"></textarea></label><button class="primary full" type="submit">Save session</button></form><div class="panel"><div class="row between"><h2>Activity · 7 days</h2><strong>${recentMinutes()} min</strong></div>${chartWeek()}<p class="small muted">${S.journal.length} total sessions. Logged data only, no estimated calories or progress claims.</p></div><h2>Sessions (${S.journal.length})</h2>${S.journal.length?S.journal.map(x=>`<div class="panel"><div class="row between"><strong>${h(x.focus)}</strong><span class="small muted">${h(x.date)}</span></div><p class="tiny muted">${h(x.type||'Training')} · ${Number(x.minutes)||0} min ${x.intensity?'· '+h(x.intensity):''}</p><p class="journal-note">${h(x.notes)}</p><button class="ghost small" data-delete-entry="${Number(x.id)}">Delete session</button></div>`).join(''):'<div class="panel muted">No sessions yet. Start with your next class.</div>'}`}

function kata(){return `<span class="eyebrow">Kata reference</span><h1>Nage no Kata</h1><p class="sub">Five sets of three formal techniques. Study the attack, response, distance, uke/tori roles, order and etiquette under an instructor.</p>${D.kata.map((set,i)=>`<details><summary><span class="ordinal">${i+1}</span> ${h(set[0])}</summary><ol class="readable-list">${set.slice(1).map(name=>`<li>${h(name)} ${videoLink(name)}</li>`).join('')}</ol></details>`).join('')}<div class="panel"><h2>Go further</h2><p>Katame no Kata, Ju no Kata and other formal Kodokan kata offer a lifetime of study.</p>${link('https://learn.usjf.com/course-overview-nage-no-kata/','USJF Nage no Kata course')}</div>`}
function resources(){return `<span class="eyebrow">Official study links</span><h1>Resources</h1><p class="sub">Use recognized judo organizations for authoritative technique, safety, kata and rule information.</p>${C.resources.map(r=>`<div class="panel"><strong>${h(r.title)}</strong><p class="small muted">${h(r.type)}</p>${link(r.url,'Visit resource')}</div>`).join('')}<p class="note small">YouTube technique links are targeted search pages rather than a verified single video. Offline lessons work without internet, but external websites and videos require a connection.</p>`}
function rankKey(){return [S.profile?.organization||'Not sure',ageGroup,targetRank||((S.profile?.rank==='White belt')?'Gokyu':'Shodan')].join('|')}
function ranksPage(){
 const org=S.profile?.organization||'Not sure',guide=R.guides[org]||R.guides['Not sure'];
 const current=targetRank||((S.profile?.rank==='White belt')?(org==='USJA'?'Rokkyu':'Gokyu'):'Shodan');
 const items=R.items(org,current,ageGroup),key=[org,ageGroup,current].join('|');
 const checked=S.rankChecks[key]||{},done=items.filter((x,i)=>checked[String(i)]).length;
 return `<div class="section-hero"><span class="eyebrow">Promotion study</span><h1>Belt progress</h1><p class="sub">Personal preparation notes for your organization. Checking a box is not promotion credit.</p></div><div class="panel rank-header"><span class="eyebrow">Your rank system</span><h2>${h(guide.title)}</h2><p>${h(guide.note)}</p>${guide.url?link(guide.url,'Read organization requirements'):''}<button class="ghost" data-go="profile">Change organization →</button></div>
 <div class="panel"><div class="rank-controls"><label>Age division<select id="ageGroup" class="field"><option value="adult" ${ageGroup==='adult'?'selected':''}>Adult / senior</option><option value="junior" ${ageGroup==='junior'?'selected':''}>Junior / youth</option></select></label><label>Grade to study<select id="rankTarget" class="field">${R.stagesFor(org,ageGroup).map(x=>`<option value="${x.value}" ${current===x.value?'selected':''}>${h(x.label)}</option>`).join('')}</select></label></div><div class="row between"><strong>${done} of ${items.length} checkpoints</strong><strong class="accent">${p(done,items.length)}%</strong></div>${progressBar(done,items.length)}</div><h2>Preparation checklist</h2>${items.map(([title,source],i)=>`<label class="rank-check"><input type="checkbox" data-toggle-rank="${i}" ${checked[String(i)]?'checked':''}><span><strong>${h(title)}</strong><small>${h(source)}</small></span></label>`).join('')}<div class="panel"><h2>Important</h2><p class="small muted">Official promotion decisions belong to the appropriate judo organization, qualified examiner and dojo. Technical quality cannot be verified by this app. Check current rules before applying, particularly for juniors.</p></div>`;
}
function videosPage(){return `<div class="section-hero"><span class="eyebrow">Watch and study</span><h1>Kodokan video library</h1><p class="sub">Direct links to the Kodokan and IJF Academy’s 100 technique demonstration series. A video is not a substitute for an instructor.</p></div><div class="panel"><div class="row between"><strong>100 individual demonstration links</strong><span class="tag">Official channel</span></div><p class="small muted">Select a technique from the encyclopedia for its video and pronunciation. These highlights are a good place to begin.</p>${link(V.channel,'Visit the Kodokan channel')}</div>${V.extras.map(v=>`<a class="video-row" href="${attr(v.url)}" rel="noopener noreferrer" target="_blank"><span class="play-tile">▶</span><span><strong>${h(v.title)}</strong><small>${h(v.topic)} · YouTube ↗</small></span><span class="chev">›</span></a>`).join('')}<div class="panel"><button class="primary full" data-go="library">Browse all 100 techniques →</button></div>`;}
function more(){return `<span class="eyebrow">More ways to learn</span><h1>Training tools</h1>${[['exercise','✦','Exercise studio','Strength, conditioning, mobility and joint care'],['train','◎','Training dashboard','Supervised mat drills and weekly stats'],['quiz','✓','Quizzes','Check your vocabulary and theory'],['kata','道','Kata library','Learn formal sequence and kata principles'],['journal','✎','Training journal','Record mat time and coaching notes'],['ranks','◉','Belt progress','Track federation specific study checklists'],['videos','▶','Video library','100 direct Kodokan technique demonstrations'],['resources','↗','Official resources','Kodokan, USJF and IJF links'],['profile','人','Learning profile','Change your rank and preferred journey'],['settings','⚙','Settings and backups','Export, import and offline help']].map(([id,icon,title,sub])=>`<button class="more-row" data-go="${id}"><span class="more-icon">${icon}</span><span><strong>${title}</strong><small>${sub}</small></span><span>›</span></button>`).join('')}`}
function profile(){return `<button class="ghost" data-go="more">← More</button><span class="eyebrow">Personalize your learning</span><h1>My judo profile</h1><form class="panel" id="profileForm"><label>Name (optional)<input class="field" name="name" maxlength="60" value="${attr(S.profile?.name||'')}"></label><label>Current rank<select class="field" name="rank">${C.rankOptions.map(([v,t])=>`<option value="${attr(v)}" ${S.profile?.rank===v?'selected':''}>${h(t)}</option>`).join('')}</select></label><label>Rank organization<select class="field" name="organization">${['Not sure','USJF','USA Judo','USJA','Kodokan','Other / local dojo'].map(v=>`<option ${S.profile?.organization===v?'selected':''} value="${attr(v)}">${h(v)}</option>`).join('')}</select></label><label>Focus<select class="field" name="goal">${C.routes.map(r=>`<option value="${r.key}" ${S.journey===r.key?'selected':''}>${h(r.title)}</option>`).join('')}</select></label><button class="primary full" type="submit">Save profile</button></form><div class="panel"><strong>Important about ranks</strong><p class="small muted">The order and colors of belts differ across associations and junior programs. Changing your belt here only changes a study label, not your official rank. Your club determines promotions.</p></div>`}
function settings(){return `<span class="eyebrow">Local data & installation</span><h1>Settings</h1><div class="panel"><h2>Back up your progress</h2><p class="sub">Lessons, flashcards, technique skill levels, judo training notes, strength workouts, preferences, quizzes and your profile live in this browser. They do not sync automatically across devices. Back up regularly.</p><div class="actions"><button class="primary" data-export>Export JSON backup</button><button class="secondary" data-import>Restore a backup</button></div><p class="tiny muted">Restoring replaces current data only after you confirm. The backup may include private training notes.</p></div><div class="panel"><h2>Study preferences</h2><label>Weekly mat time goal<select id="weeklyGoal" class="field">${[60,90,120,180,240,300].map(x=>`<option value="${x}" ${weeklyGoal()===x?'selected':''}>${x} minutes</option>`).join('')}</select></label><p class="small muted">Your training goal is personal and is not a belt promotion requirement. Audio recognition can be toggled from Flashcards.</p></div><div class="panel"><h2>Japanese pronunciation</h2><p>Tap Listen or Slow in vocabulary cards and technique pages. Your iPhone supplies the Japanese speech voice. The app does not download audio; voice quality and offline playback depend on your installed iOS voices.</p></div><div class="panel"><h2>Use it offline</h2><p>Install the PWA from Safari's Share menu using <strong>Add to Home Screen</strong>. Load the app once while online so it can cache its files. Videos and external resources still need internet access.</p></div><div class="panel"><h2>Updates</h2><p>Replace the website files on GitHub Pages. Your locally saved progress should remain if the site address, browser storage, and saved data format stay the same. Export a backup before updating.</p></div><div class="panel"><h2>Start over</h2><button class="secondary danger" data-reset>Erase local data</button></div>`}
function backup(){let blob=new Blob([JSON.stringify({app:'Judo Academy',version:5,exported:new Date().toISOString(),data:S},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='judo-academy-backup-'+today()+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function initEvents(){document.addEventListener('click',e=>{
const et=e.target.closest('[data-ex-tab]');if(et){exerciseTab=et.dataset.exTab;navigate('exercise');return;}
const ec=e.target.closest('[data-ex-category]');if(ec){exerciseCategory=ec.dataset.exCategory;render();return;}
const ep=e.target.closest('[data-ex-program]');if(ep){exerciseProgramId=ep.dataset.exProgram;exerciseHistoryId='';navigate('exerciseProgram');return;}
const em=e.target.closest('[data-ex-move]');if(em){if(page==='exerciseProgram')captureExerciseDraft();exerciseMovementId=em.dataset.exMove;exerciseHistoryId=page==='exerciseProgram'?exerciseProgramId:'';navigate('exerciseMovement');return;}
const eb=e.target.closest('[data-ex-back]');if(eb){navigate(eb.dataset.exBack);return;}
const ed=e.target.closest('[data-ex-delete]');if(ed){if(confirm('Delete this exercise workout entry?')){S.exerciseLog=S.exerciseLog.filter(x=>String(x.id)!==ed.dataset.exDelete);save();render();}return;}
const go=e.target.closest('[data-go]');if(go){navigate(go.dataset.go,go.dataset.id||'');return;}const browse=e.target.closest('[data-browse]');if(browse){const subject=browse.dataset.browse;const map={start:'first',core:'fundamentals',shodan:'blackbelt',competition:'sport',culture:'heritage'};navigate('journey',map[subject]);return;}const choice=e.target.closest('[data-filter]');if(choice){filter=choice.dataset.filter;render();return;}const cardcat=e.target.closest('[data-card-category]');if(cardcat){studyCategory=cardcat.dataset.cardCategory;activeCard=null;flipped=false;render();return;}if(e.target.closest('[data-flip]')){flipped=!flipped;render();return;}const speak=e.target.closest('[data-speak],[data-slow]');if(speak){const result=T.speak(speak.dataset.speak||speak.dataset.slow,!!speak.dataset.slow);if(!result.ok)alert(result.message);return;}
const rankChoice=e.target.closest('[data-target-rank]');if(rankChoice){targetRank=rankChoice.dataset.targetRank;render();return;}
if(e.target.closest('[data-audio-mode]')){audioMode=!audioMode;S.settings=S.settings||{};S.settings.audioMode=audioMode;save();render();return;}
const tab=e.target.closest('[data-lesson-tab]');if(tab){lessonStep=Number(tab.dataset.lessonTab);render();return;}
if(e.target.closest('[data-lesson-back]')){lessonStep=Math.max(0,lessonStep-1);render();return;}
const lnext=e.target.closest('[data-lesson-continue]');if(lnext){const id=lnext.dataset.lessonContinue;S.lessonSteps[id]=lessonChecklist(id).slice();S.lessonSteps[id][lessonStep]=true;markActivity('lesson-step',id);if(lessonStep<3){lessonStep++;}else{S.lessons[id]=true;markActivity('lesson',id)}save();render();return;}
const reflection=e.target.closest('[data-save-reflection]');if(reflection){S.reflections[reflection.dataset.saveReflection]=String(document.getElementById('lessonReflection')?.value||'').slice(0,1500);save();e.target.textContent='Saved ✓';return;}
const level=e.target.closest('[data-level]');if(level){const id=level.dataset.tech;S.skillLevels[id]=Math.max(0,Math.min(4,Number(level.dataset.level)));S.skills[id]=S.skillLevels[id]>0;markActivity('technique',id);save();render();return;}
const workout=e.target.closest('[data-workout]');if(workout){workoutId=workout.dataset.workout;render();return;}
const routineLog=e.target.closest('[data-workout-journal]');if(routineLog){journalPrefill=G.workouts.find(x=>x.id===routineLog.dataset.workoutJournal)?.focus||'';navigate('journal');return;}
const techLog=e.target.closest('[data-practice-tech]');if(techLog){journalPrefill=allTechs.find(x=>x.id===techLog.dataset.practiceTech)?.name||'';navigate('journal');return;}
const rating=e.target.closest('[data-grade]');if(rating){grade(+rating.dataset.grade);return;}if(e.target.closest('[data-start-quiz]')){beginQuiz();return;}if(e.target.closest('[data-reset-quiz]')){quiz=null;render();return;}const ans=e.target.closest('[data-answer]');if(ans&&quiz&&quiz.selected===null){quiz.selected=ans.dataset.answer;if(quiz.selected===quiz.items[quiz.index].answer)quiz.score++;render();return;}if(e.target.closest('[data-next-quiz]')&&quiz){quiz.index++;quiz.selected=null;if(quiz.index>=quiz.items.length){S.quizHistory.unshift({date:new Date().toISOString(),score:quiz.score,total:quiz.items.length});S.quizHistory=S.quizHistory.slice(0,50);save();}render();return;}if(e.target.closest('[data-export]')){backup();return;}if(e.target.closest('[data-import]')){document.getElementById('importFile').click();return;}if(e.target.closest('[data-reset]')){if(confirm('Erase ALL progress, study reviews, journal notes and your profile from this browser? Export a backup first.')){S=fresh();save();navigate('welcome')}return;}const rankCheck=e.target.closest('[data-toggle-rank]');if(rankCheck){const key=rankKey();S.rankChecks[key]=S.rankChecks[key]||{};S.rankChecks[key][rankCheck.dataset.toggleRank]=rankCheck.checked;save();render();return;}
const del=e.target.closest('[data-delete-entry]');if(del){if(confirm('Delete this training session?')){S.journal=S.journal.filter(x=>String(x.id)!==del.dataset.deleteEntry);save();render()}return;}});
document.addEventListener('change',e=>{const box=e.target;if(box.id==='xGearFilter'){exerciseGear=box.value;render();return;}if(box.matches('[data-lesson]')){S.lessons[box.dataset.lesson]=box.checked;if(box.checked)markActivity('lesson',box.dataset.lesson);save();render();return;}if(box.matches('[data-skill]')){S.skills[box.dataset.skill]=box.checked;S.skillLevels[box.dataset.skill]=box.checked?Math.max(1,skillLevel(box.dataset.skill)):0;save();render();return;}if(box.id==='ageGroup'){ageGroup=box.value;render();return;}if(box.id==='rankTarget'){targetRank=box.value;render();return;}if(box.id==='quizScope'){quizScope=box.value;return;}if(box.id==='weeklyGoal'){S.settings=S.settings||{};S.settings.weeklyGoalMinutes=Math.max(30,Math.min(600,Number(box.value)||120));save();render();return;}});
document.addEventListener('input',e=>{if(e.target.id==='exerciseSearch'){exerciseSearch=e.target.value;const node=document.getElementById('exerciseSearchResults');if(node)node.innerHTML=exerciseResults(X.exercises.filter(x=>`${x.name} ${x.group} ${x.gear}`.toLowerCase().includes(exerciseSearch.toLowerCase())));return;}if(e.target.id==='techSearch'){search=e.target.value;document.getElementById('techResults').innerHTML=renderTechs()}});
document.addEventListener('submit',e=>{
if(e.target.id==='exercisePrefsForm'){e.preventDefault();const f=new FormData(e.target);S.exercisePrefs={gear:String(f.get('gear')||'None'),experience:String(f.get('experience')||'Beginner'),judoDays:Number(f.get('judoDays'))||0,goal:String(f.get('goal')||'balanced')};save();render();return;}
if(e.target.id==='exerciseLogForm'){e.preventDefault();const w=xPrById[exerciseProgramId];if(!w)return;const done=[...document.querySelectorAll('[data-ex-done]:checked')].map(node=>node.dataset.exDone);if(!done.length){alert('Check at least one exercise you completed before saving.');return;}const form=new FormData(e.target),items=done.map(id=>({id,name:xById[id].name,load:(document.querySelector('[data-ex-load="'+id+'"]')?.value||'').slice(0,70)}));S.exerciseLog.unshift({id:Date.now(),date:new Date().toISOString(),program:w.id,title:w.title,category:w.category,minutes:Math.max(1,Math.min(360,Number(form.get('minutes'))||w.minutes)),rpe:String(form.get('rpe')||''),notes:String(form.get('notes')||'').slice(0,700),items});S.exerciseLog=S.exerciseLog.slice(0,600);delete exerciseDraft[w.id];save();exerciseTab='history';navigate('exercise');return;}
if(e.target.id==='profileForm'){e.preventDefault();let form=new FormData(e.target),rank=String(form.get('rank')||'White belt'),org=String(form.get('organization')||'Not sure'),name=String(form.get('name')||'').slice(0,60),goal=String(form.get('goal')||'first');S.profile={rank,organization:org,name,goal};S.journey=journeyByKey(goal).key;save();navigate('home');return;}if(e.target.id==='journalForm'){e.preventDefault();let form=new FormData(e.target);S.journal.unshift({id:Date.now(),date:String(form.get('date')||today()),focus:String(form.get('focus')||'Practice').slice(0,120),type:String(form.get('type')||'Training').slice(0,40),intensity:String(form.get('intensity')||'').slice(0,16),minutes:Math.max(0,Math.min(600,Number(form.get('minutes')||0))),notes:String(form.get('notes')||'').slice(0,3000)});S.journal=S.journal.slice(0,1000);journalPrefill='';markActivity('training','session');save();render();return;}});
document.getElementById('importFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>8*1024*1024)throw new Error('Backup too large');const obj=JSON.parse(await file.text()),a=obj.data;if(!a||typeof a.lessons!=='object'||typeof a.skills!=='object'||typeof a.reviews!=='object'||!Array.isArray(a.journal)||!['Judo Academy','Judo Shodan Academy'].includes(obj.app))throw new Error('This is not a supported Judo Academy backup');if(confirm('Replace the progress on this device with the contents of the backup?')){S={...fresh(),...a};if(!S.rankChecks||typeof S.rankChecks!=='object')S.rankChecks={};if(!S.skillLevels||typeof S.skillLevels!=='object')S.skillLevels={};if(!S.lessonSteps||typeof S.lessonSteps!=='object')S.lessonSteps={};if(!S.reflections||typeof S.reflections!=='object')S.reflections={};if(!Array.isArray(S.activityLog))S.activityLog=[];if(!Array.isArray(S.exerciseLog))S.exerciseLog=[];if(!S.exercisePrefs||typeof S.exercisePrefs!=='object')S.exercisePrefs={};if(!S.profile)S.profile={rank:'Ikkyu',organization:'USJF',name:'',goal:'blackbelt'};save();navigate('home')}}catch(err){alert('Import failed: '+err.message)}e.target.value='';});}
initEvents();if('serviceWorker'in navigator&&location.protocol!=='file:')window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(console.warn));render();
